        if exp != act_lines:
            mismatch.append((r, exp, act_lines, 'full'))
        else:
            matched += 1
    else:
        got = [v.strip() for v in vals[-len(exp):]] if exp else vals
        ok = (not exp and not vals) or (exp and got == [e.strip() for e in exp])
        if ok: matched += 1
        else: mismatch.append((r, exp, act_lines, 'vals'))
